INPUTS={'phage': {'bytes': 131984, 'sha256': '0f9ae48b4fe4fcd504b0fafe02accff36e359b38978a024876a6cfbffdccbcb8', 'compressed': ''}, 'helix': {'bytes': 406964, 'sha256': '1c36e7fe04b996cc02ace0f8dd583283c57382d239b89ac36c361f9951d42803', 'compressed': ''}, 'table': {'bytes': 46720, 'sha256': '78ec9cdb829e12c333ade0356adee759b8f95bdc7f037fe93ce946b0a487265b', 'compressed': ''}, 'microscope': {'bytes': 41216, 'sha256': '1a8244993548680427c67418fd7ea8cc4ca7876226924bff0f7812df4464db44', 'compressed': ''}}
